// Funnel math: rates + absolutes with drop ranking (plain JS)
function funnel(stages) {
  // stages: [{name, n}] ordered
  return stages.map((s, i) => ({
    ...s,
    rate: i === 0 ? 1 : s.n / stages[i - 1].n,
    drop: i === 0 ? 0 : 1 - s.n / stages[i - 1].n,
  }));
}
// Priority = max drop × upstream volume: rates locate, counts size the prize.

// Cohort diagonal read: same-age retention across cohorts (plain JS)
function diagonals(matrix) {
  // matrix[cohort][ageIndex] = retention
  const out = [];
  for (let age = 0; age < matrix[0].length; age++) {
    const col = matrix.map((row) => row[age]).filter((v) => v != null);
    out.push({ age, avg: col.reduce((s, v) => s + v, 0) / col.length });
  }
  return out;
}
// Diagonals answer 'is retention improving?' — rows answer 'how cohorts age?'

