    name: s.name,
    rate: i === 0 ? 100 : Math.round((s.n / stages[i - 1].n) * 1000) / 10,
    drop: i === 0 ? 0 : Math.round((1 - s.n / stages[i - 1].n) * 1000) / 10,
  }));
